import unicodedata
from typing import Iterable

def graphemes(text: str) -> Iterable[str]:
    """Yields each grapheme cluster from the text."""
    if not text:
        return

    current_grapheme = ""
    join_next = False
    for char in text:
        if join_next:
            current_grapheme += char
            join_next = False
        elif current_grapheme and unicodedata.combining(char) > 0:
            current_grapheme += char
        elif char == "\u200d":
            current_grapheme += char
            join_next = True
        elif current_grapheme:
            yield current_grapheme
            current_grapheme = char
        else:
            current_grapheme = char

    if current_grapheme:
        yield current_grapheme

def get_character_cell_size(character: str) -> int:
    # Mocking the real function for now
    # In reality, this would use CELL_WIDTHS
    if unicodedata.combining(character) > 0 or character == "\u200d":
        return 0
    return 1 # Simplified

def get_grapheme_cell_size(grapheme: str) -> int:
    return sum(get_character_cell_size(char) for char in grapheme)

