    ("hello", ["h", "e", "l", "l", "o"]),
    ("a\u0301", ["a\u0301"]), # a with acute accent
    ("👨‍👩‍👧‍👦", ["👨‍👩‍👧‍👦"]), # Family emoji (ZWJ sequence)
    ("👨‍👩", ["👨‍👩"]), # Couple emoji (ZWJ sequence)
    ("a\u0301b", ["a\u0301", "b"]),
]

for text, expected in test_cases:
    result = list(graphemes(text))
    assert result == expected, f"Failed for {text!r}: expected {expected!r}, got {result!r}"
    for g in result:
        print(f"Grapheme: {g!r}, Width: {get_grapheme_cell_size(g)}")

print("All tests passed!")

